use std::path::PathBuf;

use clap::{Parser, Subcommand};

use crate::providers::Provider;
use crate::usage;

#[derive(Parser, Debug)]
#[command(
    name = "communique",
    version,
    about = "Editorialized release notes powered by AI"
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,

    /// Enable verbose logging output
    #[arg(long, short, global = true)]
    pub verbose: bool,

    /// Suppress progress output
    #[arg(long, short, global = true)]
    pub quiet: bool,

    /// Path to config file (default: communique.toml in repo root)
    #[arg(long, short, global = true)]
    pub config: Option<PathBuf>,
}

#[derive(Subcommand, Debug)]
pub enum Command {
    /// Generate release notes for a git tag
    Generate {
        /// Git tag to generate release notes for
        tag: String,

        /// Previous tag (auto-detected if omitted)
        prev_tag: Option<String>,

        /// Push editorialized notes to the GitHub release
        #[arg(long)]
        github_release: bool,

        /// Update CHANGELOG.md with the generated changelog entry
        #[arg(long)]
        changelog: bool,

        /// Output concise changelog entry instead of detailed notes
        #[arg(long)]
        concise: bool,

        /// Generate notes without updating GitHub or verifying links
        #[arg(long, short = 'n')]
        dry_run: bool,

        /// GitHub repo in owner/repo format (auto-detected from git remote)
        #[arg(long)]
        repo: Option<String>,

        /// LLM model to use
        #[arg(long)]
        model: Option<String>,

        /// Max response tokens
        #[arg(long)]
        max_tokens: Option<u32>,

        /// LLM provider (anthropic or openai, auto-detected from model if omitted)
        #[arg(long)]
        provider: Option<Provider>,

        /// Base URL for the LLM API
        #[arg(long)]
        base_url: Option<String>,

        /// Write output to a file instead of stdout
        #[arg(long, short)]
        output: Option<PathBuf>,
    },

    /// Generate a communique.toml config file in the repo root
    Init {
        /// Overwrite existing config file
        #[arg(long)]
        force: bool,
    },

    /// Show the companies sponsoring communique and the jdx.dev open source tools
    Sponsors,

    Usage(usage::Usage),
}
use std::path::{Path, PathBuf};

use regex::Regex;
use xx::git::Git;
use xx::process;

use crate::error::{Error, Result};

pub fn repo_root() -> Result<PathBuf> {
    let path = process::cmd("git", ["rev-parse", "--show-toplevel"]).read()?;
    Ok(PathBuf::from(path))
}

pub fn detect_remote(repo_root: &Path) -> Result<String> {
    let git = Git::new(repo_root.to_path_buf());
    let url = git
        .get_remote_url()
        .ok_or_else(|| Error::Git("no origin remote found".into()))?;
    parse_owner_repo(&url)
}

fn parse_owner_repo(url: &str) -> Result<String> {
    // SSH: git@github.com:owner/repo.git
    if let Some(rest) = url.strip_prefix("git@github.com:") {
        let repo = rest.trim_end_matches(".git");
        return Ok(repo.to_string());
    }
    // HTTPS: https://github.com/owner/repo.git
    if let Some(rest) = url
        .strip_prefix("https://github.com/")
        .or_else(|| url.strip_prefix("http://github.com/"))
    {
        let repo = rest.trim_end_matches(".git");
        return Ok(repo.to_string());
    }
    Err(Error::Git(format!(
        "cannot parse GitHub repo from remote URL: {url}"
    )))
}

pub fn previous_tag(repo_root: &Path, current_tag: &str) -> Result<String> {
    let stdout = process::cmd("git", ["tag", "--sort=-v:refname"])
        .cwd(repo_root)
        .read()?;

    let tags: Vec<&str> = stdout
        .lines()
        .map(str::trim)
        .filter(|t| !t.is_empty())
        .collect();

    // If current_tag is in the tag list, return the one after it (next oldest)
    let mut found = false;
    for tag in &tags {
        if found {
            return Ok(tag.to_string());
        }
        if *tag == current_tag {
            found = true;
        }
    }

    // If current_tag was found but there's no previous tag, or if there are
    // no tags at all, fall back to the root commit so we capture all history.
    if found || tags.is_empty() {
        return root_commit(repo_root);
    }

    // current_tag is not in the tag list (e.g. HEAD, branch, commit SHA, or
    // a version that isn't tagged yet). Fall back to the most recent tag.
    Ok(tags[0].to_string())
}

fn root_commit(repo_root: &Path) -> Result<String> {
    let sha = process::cmd("git", ["rev-list", "--max-parents=0", "HEAD"])
        .cwd(repo_root)
        .read()?;
    sha.lines()
        .next()
        .map(|s| s.trim().to_string())
        .ok_or_else(|| Error::Git("no commits found".into()))
}

/// Resolve a ref to a commit, falling back to HEAD if the ref doesn't exist
/// (e.g. a version tag that hasn't been created yet).
pub fn resolve_ref(repo_root: &Path, git_ref: &str) -> Result<String> {
    let result = process::cmd("git", ["rev-parse", "--verify", "--quiet", git_ref])
        .cwd(repo_root)
        .stderr_capture()
        .read();
    match result {
        Ok(sha) => Ok(sha.trim().to_string()),
        Err(_) => {
            let sha = process::cmd("git", ["rev-parse", "HEAD"])
                .cwd(repo_root)
                .read()?;
            Ok(sha.trim().to_string())
        }
    }
}

pub fn log_between(repo_root: &Path, from: &str, to: &str) -> Result<String> {
    let from = resolve_ref(repo_root, from)?;
    let to = resolve_ref(repo_root, to)?;
    let range = format!("{from}..{to}");
    let output = process::cmd("git", ["log", &range, "--pretty=format:%h %s", "--reverse"])
        .cwd(repo_root)
        .read()?;
    Ok(output)
}

pub fn extract_pr_numbers(log: &str) -> Vec<u64> {
    let re = Regex::new(r"\(#(\d+)\)").unwrap();
    re.captures_iter(log)
        .filter_map(|cap| cap[1].parse().ok())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_parse_owner_repo_ssh() {
        assert_eq!(
            parse_owner_repo("git@github.com:jdx/pitchfork.git").unwrap(),
            "jdx/pitchfork"
        );
    }

    #[test]
    fn test_parse_owner_repo_https() {
        assert_eq!(
            parse_owner_repo("https://github.com/jdx/pitchfork.git").unwrap(),
            "jdx/pitchfork"
        );
    }

    #[test]
    fn test_extract_pr_numbers() {
        let log =
            "abc1234 feat: add feature (#123)\ndef5678 fix: bug (#456)\nghi9012 chore: update deps";
        assert_eq!(extract_pr_numbers(log), vec![123, 456]);
    }

    #[test]
    fn test_resolve_ref_existing() {
        let repo = crate::test_helpers::TempRepo::new();
        repo.write_file("f.txt", "a");
        repo.commit("first");
        repo.tag("v1.0.0");

        let sha = resolve_ref(repo.path(), "v1.0.0").unwrap();
        assert!(!sha.is_empty());
        assert_eq!(sha.len(), 40);
    }

    #[test]
    fn test_resolve_ref_fallback_to_head() {
        let repo = crate::test_helpers::TempRepo::new();
        repo.write_file("f.txt", "a");
        repo.commit("first");

        let sha = resolve_ref(repo.path(), "nonexistent-tag").unwrap();
        assert_eq!(sha.len(), 40);
    }

    #[test]
    fn test_previous_tag() {
        let repo = crate::test_helpers::TempRepo::new();
        repo.write_file("f.txt", "a");
        repo.commit("first");
        repo.tag("v1.0.0");
        repo.write_file("f.txt", "b");
        repo.commit("second");
        repo.tag("v2.0.0");

        let prev = previous_tag(repo.path(), "v2.0.0").unwrap();
        assert_eq!(prev, "v1.0.0");
    }

    #[test]
    fn test_previous_tag_first_release() {
        let repo = crate::test_helpers::TempRepo::new();
        repo.write_file("f.txt", "a");
        repo.commit("first");
        repo.tag("v1.0.0");

        // No previous tag — should fall back to root commit SHA
        let prev = previous_tag(repo.path(), "v1.0.0").unwrap();
        assert_eq!(prev.len(), 40);
    }

    #[test]
    fn test_log_between() {
        let repo = crate::test_helpers::TempRepo::new();
        repo.write_file("f.txt", "a");
        repo.commit("first commit");
        repo.tag("v1.0.0");
        repo.write_file("f.txt", "b");
        repo.commit("second commit");
        repo.tag("v2.0.0");

        let log = log_between(repo.path(), "v1.0.0", "v2.0.0").unwrap();
        assert!(log.contains("second commit"));
        assert!(!log.contains("first commit"));
    }
}
pub fn system_prompt(extra: Option<&str>, emoji: bool) -> String {
    let mut prompt = r#"You are an expert technical writer generating release notes for a software project.

You have access to tools to browse the repository:
- read_file: Read contents of a git-tracked file (path relative to repo root)
- list_files: List tracked files, optionally filtered by glob
- grep: Search file contents with ripgrep
- get_pr: Fetch GitHub PR details (title, body, labels, author)
- get_pr_diff: Fetch the diff for a GitHub PR
- get_issue: Fetch GitHub issue details (title, body, labels, state)
- git_show: Show full details of a commit (message, author, diff)
- get_commits: List commits between refs or for a specific file path

Use these tools to understand what changed and why. Read relevant source files, PR descriptions, and diffs to write accurate, insightful release notes.

When you are done researching, call the `submit_release_notes` tool with three fields:

### `changelog`
A concise changelog entry using Keep a Changelog categories (## Added, ## Fixed, etc). No version header — just the categorized bullet points. Reference relevant PRs, issues, and commits as markdown links — e.g. `[#123](https://github.com/OWNER/REPO/pull/123)` for PRs/issues or `[abc1234](https://github.com/OWNER/REPO/commit/abc1234)` for commits.

### `release_title`
A catchy, concise title for the GitHub release (no # prefix, no version tag — the version will be prepended automatically as "vX.Y.Z: your title").

### `release_body`
Detailed GitHub release notes in markdown. Use the following template as a base, including or omitting sections as appropriate for the release:

```
<brief narrative summary — 1-2 sentences describing the release at a high level>

## Highlights
<!-- Omit this section unless the release is broad enough that readers need an executive summary. -->
<!-- Include it only for large releases with roughly 10+ distinct user-facing changes or 4+ independent headline themes. -->
<!-- If included, write 2-3 synthesis bullets that group related work; do not repeat the same bullets that appear in the categorized sections. -->

## Added / ## Fixed / ## Changed / etc.
<!-- Use top-level ## headings for each category (Added, Fixed, Changed, Deprecated, Removed). Only include categories that apply. -->
<!-- Each item should mention the PR (@author) where relevant -->
<!-- Where it genuinely helps, include a brief code snippet, usage example, or config sample -->

## Breaking Changes
<!-- Only if applicable. List any changes that require user action to upgrade. -->

## New Contributors
<!-- List first-time contributors to the project, with a link to their first PR -->
<!-- e.g. * @username made their first contribution in #123 -->
<!-- Omit this section if there are no new contributors -->

**Full Changelog**: https://github.com/OWNER/REPO/compare/PREV_TAG...TAG
```

Adapt the template to fit the release. Small releases might only need a summary and categorized sections, regardless of whether the version is patch, minor, or major. Most releases should omit Highlights; use it only when it reduces scanning effort instead of duplicating the sections below. Don't include empty sections.

Each section needs a distinct job:
- The opening paragraph frames the release in 1-2 sentences.
- Highlights, when present, group broad themes for skimming; they should not be a second categorized changelog.
- Categorized sections carry the concrete details, PR links, authors, examples, and compatibility notes.

Avoid saying the same change three times. If a change appears in Highlights, keep the categorized bullet focused on extra detail or omit the duplicate detail entirely. Prefer fewer, denser bullets over repeated summaries.

## Guidelines

Write clearly and concisely. Focus on what matters to END USERS of the software. Do NOT fabricate changes — only describe what you can verify from the git log, PRs, and source code.

IMPORTANT: Only include changes that affect end users. Omit purely internal changes such as CI/CD pipeline updates, linter configurations, pre-commit hooks, build caching, code formatting, internal refactors, dependency updates (unless they fix a user-facing bug or add a user-facing feature), and dev tooling changes. If a release has no user-facing changes, say so briefly rather than padding the notes with internal details.

Be honest about the scope of a release. If it only has one or two user-facing changes, say that — don't inflate it into something bigger than it is. A short, accurate release note is always better than a long, padded one."#.to_string();

    if !emoji {
        prompt.push_str("\n\nDo NOT use emoji anywhere in the output — not in headings, titles, bullet points, or prose.");
    }

    if let Some(extra) = extra {
        prompt.push_str("\n\n");
        prompt.push_str(extra);
    }

    prompt
}

pub struct UserPromptContext<'a> {
    pub tag: &'a str,
    pub prev_tag: &'a str,
    pub owner_repo: &'a str,
    pub git_log: &'a str,
    pub pr_numbers: &'a [u64],
    pub is_unreleased_head: bool,
    pub changelog_entry: Option<&'a str>,
    pub existing_release: Option<&'a str>,
    pub context: Option<&'a str>,
    pub recent_releases: &'a [(String, String)],
}

pub fn user_prompt(ctx: &UserPromptContext) -> String {
    let UserPromptContext {
        tag,
        prev_tag,
        owner_repo,
        git_log,
        pr_numbers,
        is_unreleased_head,
        changelog_entry,
        existing_release,
        context,
        recent_releases,
    } = ctx;
    let mut parts = Vec::new();

    if let Some(ctx) = context {
        parts.push(format!("## Project Context\n{ctx}"));
    }

    let release_request = if *is_unreleased_head {
        format!("Generate release notes for unreleased changes since {prev_tag}.")
    } else {
        format!("Generate release notes for **{tag}** (previous release: {prev_tag}).")
    };

    parts.push(format!(
        "{release_request}\n\
         Repository: `{owner_repo}` (https://github.com/{owner_repo})\n\n\
         ## Git Log\n```\n{git_log}\n```"
    ));

    if !pr_numbers.is_empty() {
        let prs = pr_numbers
            .iter()
            .map(|n| format!("#{n}"))
            .collect::<Vec<_>>()
            .join(", ");
        parts.push(format!(
            "\n## Referenced PRs\n{prs}\n\nUse the `get_pr` and `get_pr_diff` tools to understand these changes in detail."
        ));
    }

    if let Some(entry) = changelog_entry {
        if *is_unreleased_head {
            parts.push(format!(
                "\n## Existing Unreleased CHANGELOG.md Draft\nHere is the current draft unreleased material — reconcile it with the generated notes and improve it. Produce only the changelog section body, without a nested `## [Unreleased]` or `## Unreleased` heading:\n```\n{entry}\n```"
            ));
        } else {
            parts.push(format!(
                "\n## Existing CHANGELOG.md Entry\nHere is the current auto-generated entry — use it as a starting point and improve it:\n```\n{entry}\n```"
            ));
        }
    }

    if let Some(body) = existing_release {
        parts.push(format!(
            "\n## Existing GitHub Release Body\nHere are the current auto-generated release notes — editorialize and improve them:\n```\n{body}\n```"
        ));
    }

    if !recent_releases.is_empty() {
        let mut section = String::from(
            "\n## Style Reference (Recent Releases)\nMatch the tone, structure, and formatting of these recent release notes:\n",
        );
        for (tag_name, body) in *recent_releases {
            let truncated = if body.len() > 3072 {
                let mut end = 3072;
                while !body.is_char_boundary(end) {
                    end -= 1;
                }
                format!("{}...\n[truncated]", &body[..end])
            } else {
                body.clone()
            };
            section.push_str(&format!("\n### {tag_name}\n```\n{truncated}\n```\n"));
        }
        parts.push(section);
    }

    parts.push("\nBrowse the repository as needed to understand the changes, then call `submit_release_notes` with the final output.".into());

    parts.join("\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_system_prompt_default() {
        let prompt = system_prompt(None, true);
        assert!(prompt.contains("submit_release_notes"));
        assert!(prompt.contains("Keep a Changelog"));
        assert!(prompt.contains("10+ distinct user-facing changes"));
        assert!(prompt.contains("do not repeat the same bullets"));
        assert!(prompt.contains("Each section needs a distinct job"));
        assert!(!prompt.contains("Do NOT use emoji"));
    }

    #[test]
    fn test_system_prompt_no_emoji() {
        let prompt = system_prompt(None, false);
        assert!(prompt.contains("Do NOT use emoji"));
    }

    #[test]
    fn test_system_prompt_with_extra() {
        let prompt = system_prompt(Some("Always mention cats"), true);
        assert!(prompt.contains("Always mention cats"));
    }

    #[test]
    fn test_user_prompt_minimal() {
        let prompt = user_prompt(&UserPromptContext {
            tag: "v1.0.0",
            prev_tag: "v0.9.0",
            owner_repo: "jdx/communique",
            git_log: "abc1234 feat: add feature",
            pr_numbers: &[],
            is_unreleased_head: false,
            changelog_entry: None,
            existing_release: None,
            context: None,
            recent_releases: &[],
        });
        assert!(prompt.contains("v1.0.0"));
        assert!(prompt.contains("v0.9.0"));
        assert!(prompt.contains("jdx/communique"));
        assert!(prompt.contains("abc1234 feat: add feature"));
        assert!(!prompt.contains("Referenced PRs"));
        assert!(!prompt.contains("CHANGELOG.md"));
        assert!(!prompt.contains("Style Reference"));
    }

    #[test]
    fn test_user_prompt_with_prs() {
        let prompt = user_prompt(&UserPromptContext {
            tag: "v1.0.0",
            prev_tag: "v0.9.0",
            owner_repo: "jdx/communique",
            git_log: "abc1234 feat (#42)",
            pr_numbers: &[42, 99],
            is_unreleased_head: false,
            changelog_entry: None,
            existing_release: None,
            context: None,
            recent_releases: &[],
        });
        assert!(prompt.contains("Referenced PRs"));
        assert!(prompt.contains("#42"));
        assert!(prompt.contains("#99"));
        assert!(prompt.contains("get_pr"));
    }

    #[test]
    fn test_user_prompt_full() {
        let prompt = user_prompt(&UserPromptContext {
            tag: "v2.0.0",
            prev_tag: "v1.0.0",
            owner_repo: "jdx/communique",
            git_log: "def5678 fix: bug",
            pr_numbers: &[10],
            is_unreleased_head: false,
            changelog_entry: Some("### Fixed\n- Bug fix"),
            existing_release: Some("Previous release body"),
            context: Some("This is a CLI tool for release notes."),
            recent_releases: &[("v1.0.0".into(), "Release 1.0 notes".into())],
        });
        assert!(prompt.contains("Project Context"));
        assert!(prompt.contains("CLI tool for release notes"));
        assert!(prompt.contains("CHANGELOG.md Entry"));
        assert!(prompt.contains("Bug fix"));
        assert!(prompt.contains("Existing GitHub Release Body"));
        assert!(prompt.contains("Previous release body"));
        assert!(prompt.contains("Style Reference"));
        assert!(prompt.contains("Release 1.0 notes"));
    }

    #[test]
    fn test_user_prompt_recent_releases_truncation() {
        let long_body = "x".repeat(5000);
        let prompt = user_prompt(&UserPromptContext {
            tag: "v2.0.0",
            prev_tag: "v1.0.0",
            owner_repo: "test/repo",
            git_log: "abc init",
            pr_numbers: &[],
            is_unreleased_head: false,
            changelog_entry: None,
            existing_release: None,
            context: None,
            recent_releases: &[("v1.0.0".into(), long_body)],
        });
        assert!(prompt.contains("[truncated]"));
    }

    #[test]
    fn test_user_prompt_unreleased_head_labels_changes_without_head() {
        let prompt = user_prompt(&UserPromptContext {
            tag: "HEAD",
            prev_tag: "v1.0.0",
            owner_repo: "test/repo",
            git_log: "abc1234 feat: draft feature",
            pr_numbers: &[],
            is_unreleased_head: true,
            changelog_entry: None,
            existing_release: None,
            context: None,
            recent_releases: &[],
        });

        assert!(prompt.contains("Generate release notes for unreleased changes since v1.0.0."));
        assert!(!prompt.contains("**HEAD**"));
    }

    #[test]
    fn test_user_prompt_tagged_mode_preserves_tagged_phrase() {
        let prompt = user_prompt(&UserPromptContext {
            tag: "v2.0.0",
            prev_tag: "v1.0.0",
            owner_repo: "test/repo",
            git_log: "abc1234 feat: tagged feature",
            pr_numbers: &[],
            is_unreleased_head: false,
            changelog_entry: None,
            existing_release: None,
            context: None,
            recent_releases: &[],
        });

        assert!(
            prompt.contains("Generate release notes for **v2.0.0** (previous release: v1.0.0).")
        );
    }

    #[test]
    fn test_user_prompt_unreleased_changelog_entry_is_draft_material() {
        let prompt = user_prompt(&UserPromptContext {
            tag: "HEAD",
            prev_tag: "v1.0.0",
            owner_repo: "test/repo",
            git_log: "abc1234 feat: draft feature",
            pr_numbers: &[],
            is_unreleased_head: true,
            changelog_entry: Some("### Changed\n- Old draft"),
            existing_release: None,
            context: None,
            recent_releases: &[],
        });

        assert!(prompt.contains("Existing Unreleased CHANGELOG.md Draft"));
        assert!(prompt.contains("draft unreleased material"));
        assert!(prompt.contains("without a nested `## [Unreleased]` or `## Unreleased` heading"));
        assert!(!prompt.contains("Existing CHANGELOG.md Entry"));
        assert!(!prompt.contains("**HEAD**"));
    }

    #[test]
    fn test_user_prompt_recent_releases_truncation_on_char_boundary() {
        // Ensure truncation does not panic when the 3072-byte cutoff lands
        // inside a multi-byte UTF-8 character (e.g. the em-dash '—', 3 bytes).
        let mut body = "a".repeat(3070);
        body.push('—');
        body.push_str(&"b".repeat(2000));
        let prompt = user_prompt(&UserPromptContext {
            tag: "v2.0.0",
            prev_tag: "v1.0.0",
            owner_repo: "test/repo",
            git_log: "abc init",
            pr_numbers: &[],
            is_unreleased_head: false,
            changelog_entry: None,
            existing_release: None,
            context: None,
            recent_releases: &[("v1.0.0".into(), body)],
        });
        assert!(prompt.contains("[truncated]"));
    }
}
use std::path::{Path, PathBuf};
use std::sync::Arc;

use clx::progress::{ProgressJob, ProgressJobBuilder, ProgressStatus};
use log::info;

use crate::config::Defaults;
use crate::llm::LlmClient;
use crate::output::ParsedOutput;
use crate::providers::{self, Provider};
use crate::{agent, config, git, github, prompt, tools};

pub struct GenerateOptions {
    pub tag: String,
    pub prev_tag: Option<String>,
    pub github_release: bool,
    pub changelog: bool,
    pub concise: bool,
    pub dry_run: bool,
    pub repo: Option<String>,
    pub model: Option<String>,
    pub max_tokens: Option<u32>,
    pub provider: Option<Provider>,
    pub base_url: Option<String>,
    pub output: Option<PathBuf>,
    pub config: Option<PathBuf>,
}

struct Context {
    repo_root: PathBuf,
    #[allow(dead_code)]
    owner_repo: String,
    tag: String,
    prev_tag: String,
    client: Box<dyn LlmClient>,
    defaults: Defaults,
    system_extra: Option<String>,
    context: Option<String>,
    github_client: Option<github::GitHubClient>,
}

impl Context {
    fn is_unreleased_head(&self) -> bool {
        self.tag == "HEAD"
    }

    fn display_tag(&self) -> &str {
        if self.is_unreleased_head() {
            "Unreleased"
        } else {
            &self.tag
        }
    }
}

fn validate_generate_options(opts: &GenerateOptions) -> miette::Result<()> {
    if opts.github_release && opts.tag == "HEAD" {
        return Err(miette::miette!(
            "--github-release cannot be used with HEAD because HEAD is an unreleased changelog target. Use --changelog, or generate notes for a real tag."
        ));
    }

    Ok(())
}

fn release_title_description<'a>(title: &'a str, label: &str) -> Option<&'a str> {
    let rest = title.strip_prefix(label)?;
    if rest.chars().next().is_some_and(char::is_alphanumeric) {
        return None;
    }

    let trimmed = rest.trim_start_matches(|c: char| !c.is_alphanumeric());
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed)
    }
}

fn normalize_release_title(title: String, display_tag: &str, raw_tag: &str) -> String {
    let tag_prefix = format!("{display_tag}: ");
    if title.starts_with(&tag_prefix) {
        return title;
    }

    if raw_tag != display_tag && (title.trim() == raw_tag || title.trim() == display_tag) {
        return format!("{display_tag}: changes");
    }

    let description = release_title_description(&title, display_tag)
        .or_else(|| {
            if raw_tag == display_tag {
                None
            } else {
                release_title_description(&title, raw_tag)
            }
        })
        .unwrap_or(title.as_str());

    format!("{display_tag}: {description}")
}

pub async fn run(opts: GenerateOptions) -> miette::Result<()> {
    validate_generate_options(&opts)?;

    let job = ProgressJobBuilder::new()
        .body("{{spinner()}} {{message | flex}}")
        .prop("message", "Discovering repository...")
        .start();

    let ctx = gather_context(&opts, &job).await?;
    let mut parsed = generate_notes(&ctx, opts.dry_run, &job).await?;

    // Normalize release title to "label: description" format.
    // The LLM may include the tag with a different separator (e.g. "v1.0.0 (title)"
    // or "v1.0.0 - title"), so we check for the exact "label: " prefix.
    let display_tag = ctx.display_tag();
    parsed.release_title = normalize_release_title(parsed.release_title, display_tag, &ctx.tag);

    publish(&opts, &ctx, &parsed, &job).await?;

    if opts.changelog {
        update_changelog(&ctx, &parsed, opts.dry_run, &job).await?;
    }

    job.set_status(ProgressStatus::Done);
    job.prop("message", "Done");
    clx::progress::flush();

    let u = &parsed.usage;
    eprintln!(
        "Tokens: {} input + {} output = {} total",
        u.input_tokens,
        u.output_tokens,
        u.input_tokens + u.output_tokens
    );

    let text = if opts.concise {
        parsed.changelog.clone()
    } else {
        format!("# {}\n\n{}", parsed.release_title, parsed.release_body)
    };

    if let Some(path) = &opts.output {
        xx::file::write(path, &text)?;
    } else {
        println!("{text}");
    }

    Ok(())
}

async fn gather_context(opts: &GenerateOptions, job: &Arc<ProgressJob>) -> miette::Result<Context> {
    let github_token = std::env::var("GITHUB_TOKEN").ok();

    if opts.github_release && github_token.is_none() {
        return Err(crate::error::Error::GitHub(
            "GITHUB_TOKEN is required for --github-release".into(),
        ))?;
    }

    let repo_root = git::repo_root()?;
    info!("repo root: {}", repo_root.display());

    let config = match &opts.config {
        Some(path) => config::Config::load_from(path)?,
        None => config::Config::load(&repo_root)?,
    }
    .unwrap_or_default();
    let defaults = config.defaults.unwrap_or_default();

    let model = opts
        .model
        .clone()
        .or(defaults.model.clone())
        .unwrap_or_else(|| "claude-opus-4-8".into());
    let max_tokens = opts.max_tokens.or(defaults.max_tokens).unwrap_or(4096);
    let owner_repo = match opts.repo.clone().or(defaults.repo.clone()) {
        Some(r) => r,
        None => git::detect_remote(&repo_root)?,
    };
    info!("repo: {owner_repo}");

    // Determine provider
    let provider = opts
        .provider
        .clone()
        .or(defaults.provider.clone())
        .unwrap_or_else(|| providers::detect_provider(&model));
    info!("provider: {provider:?}, model: {model}");

    // Resolve API key based on provider
    let api_key = match &provider {
        Provider::Anthropic => std::env::var("ANTHROPIC_API_KEY")
            .map_err(|_| crate::error::Error::Llm("ANTHROPIC_API_KEY not set".into()))?,
        Provider::OpenAI => std::env::var("OPENAI_API_KEY")
            .or_else(|_| std::env::var("LLM_API_KEY"))
            .unwrap_or_default(),
    };

    let base_url = opts
        .base_url
        .clone()
        .or(defaults.base_url.clone())
        .and_then(|u| if u.is_empty() { None } else { Some(u) });

    let client = providers::build_client(&provider, api_key, model, max_tokens, base_url);

    let prev_tag = match &opts.prev_tag {
        Some(t) => t.clone(),
        None => git::previous_tag(&repo_root, &opts.tag)?,
    };
    info!("range: {prev_tag}..{}", opts.tag);

    job.prop(
        "message",
        &format!("Reading git log {prev_tag}..{}...", opts.tag),
    );

    let github_client = github_token
        .as_ref()
        .map(|token| github::GitHubClient::new(token.clone(), &owner_repo))
        .transpose()?;

    Ok(Context {
        repo_root,
        owner_repo,
        tag: opts.tag.clone(),
        prev_tag,
        client,
        defaults,
        system_extra: config.system_extra,
        context: config.context,
        github_client,
    })
}

async fn generate_notes(
    ctx: &Context,
    dry_run: bool,
    job: &Arc<ProgressJob>,
) -> miette::Result<ParsedOutput> {
    let git_log = git::log_between(&ctx.repo_root, &ctx.prev_tag, &ctx.tag)?;
    let pr_numbers = git::extract_pr_numbers(&git_log);
    info!(
        "found {} commits, {} PRs",
        git_log.lines().count(),
        pr_numbers.len()
    );

    job.prop("message", "Fetching existing release context...");
    let changelog_entry = if ctx.is_unreleased_head() {
        read_unreleased_section(&ctx.repo_root)?
    } else {
        read_changelog_entry(&ctx.repo_root, &ctx.tag)
    };

    // Fetch existing release and recent releases in parallel
    let match_style = ctx.defaults.match_style.unwrap_or(true);
    let (existing_release, recent_releases) = if let Some(gh) = &ctx.github_client {
        let existing_fut = async {
            if ctx.is_unreleased_head() {
                Ok(None)
            } else {
                gh.get_release_by_tag(&ctx.tag).await
            }
        };
        let recent_fut = async {
            if !match_style {
                return vec![];
            }
            match gh.list_recent_releases(3).await {
                Ok(releases) => releases
                    .into_iter()
                    .filter(|r| r.tag_name != ctx.tag)
                    .filter_map(|r| {
                        let body = r.body.unwrap_or_default();
                        if body.is_empty() {
                            None
                        } else {
                            Some((r.tag_name, body))
                        }
                    })
                    .take(2)
                    .collect(),
                Err(e) => {
                    info!("failed to fetch recent releases for style matching: {e}");
                    vec![]
                }
            }
        };
        let (existing_result, recent) = tokio::join!(existing_fut, recent_fut);
        let existing = match existing_result? {
            Some(r) => r.body,
            None => None,
        };
        (existing, recent)
    } else {
        (None, vec![])
    };

    let emoji = ctx.defaults.emoji.unwrap_or(true);
    let system = prompt::system_prompt(ctx.system_extra.as_deref(), emoji);
    let user_msg = prompt::user_prompt(&prompt::UserPromptContext {
        tag: &ctx.tag,
        prev_tag: &ctx.prev_tag,
        owner_repo: &ctx.owner_repo,
        git_log: &git_log,
        pr_numbers: &pr_numbers,
        is_unreleased_head: ctx.is_unreleased_head(),
        changelog_entry: changelog_entry.as_deref(),
        existing_release: existing_release.as_deref(),
        context: ctx.context.as_deref(),
        recent_releases: &recent_releases,
    });

    job.prop("message", "Generating release notes...");
    let tool_defs = tools::all_definitions(ctx.github_client.is_some());

    let verify_links = !dry_run && ctx.defaults.verify_links.unwrap_or(true);

    agent::run(agent::AgentContext {
        client: &*ctx.client,
        system: &system,
        user_message: &user_msg,
        tool_defs,
        repo_root: &ctx.repo_root,
        github: ctx.github_client.as_ref(),
        verify_links,
        job,
    })
    .await
    .map_err(Into::into)
}

async fn publish(
    opts: &GenerateOptions,
    ctx: &Context,
    parsed: &ParsedOutput,
    job: &Arc<ProgressJob>,
) -> miette::Result<()> {
    if opts.github_release && !opts.dry_run {
        job.prop(
            "message",
            &format!("Updating GitHub release for {}...", ctx.tag),
        );
        let gh = ctx.github_client.as_ref().unwrap();
        match gh.get_release_by_tag(&ctx.tag).await? {
            Some(release) => {
                gh.update_release(
                    release.id,
                    Some(&parsed.release_title),
                    Some(&parsed.release_body),
                )
                .await?;
            }
            None => {
                job.set_status(ProgressStatus::Warn);
                job.prop(
                    "message",
                    &format!("No GitHub release found for {} — skipping update", ctx.tag),
                );
            }
        }
    }

    Ok(())
}

