impl Config {
    pub fn load(repo_root: &Path) -> Result<Option<Config>> {
        let path = repo_root.join("communique.toml");
        Self::load_from(&path)
    }

    pub fn load_from(path: &Path) -> Result<Option<Config>> {
        if !path.exists() {
            return Ok(None);
        }
        let contents = xx::file::read_to_string(path)?;
        let config: Config = toml::from_str(&contents).map_err(|e| {
            let span = e.span().map(|s| s.into()).unwrap_or((0, 0).into());
            crate::error::Error::Toml {
                message: e.message().to_string(),
                src: miette::NamedSource::new(path.display().to_string(), contents.clone()),
                span,
            }
        })?;
        config.validate()?;
        Ok(Some(config))
    }

    fn validate(&self) -> Result<()> {
        if let Some(defaults) = &self.defaults {
            if let Some(max_tokens) = defaults.max_tokens
                && max_tokens == 0
            {
                return Err(crate::error::Error::Config(
                    "max_tokens must be greater than 0".into(),
                ));
            }
            if let Some(repo) = &defaults.repo
                && (!repo.contains('/') || repo.starts_with('/') || repo.ends_with('/'))
            {
                return Err(crate::error::Error::Config(format!(
                    "invalid repo '{repo}' (expected 'owner/repo' format)"
                )));
            }
        }
        Ok(())
    }

    pub fn template() -> &'static str {
        TEMPLATE
    }
}

