pub fn previous_tag_filtered(repo_root: &Path, current_tag: &str, pattern: Option<&str>, channel: crate::workflow::Channel) -> Result<String> {
    let target = resolve_ref(repo_root, current_tag)?;
    let stdout = process::cmd("git", ["tag", "--merged", &target, "--sort=-v:refname", "--list", pattern.unwrap_or("*")])
