}

pub fn log_between_paths(repo_root: &Path, from: &str, to: &str, paths: &[String]) -> Result<String> {
    let from = verify_ref(repo_root, from)?;
    let to = resolve_ref(repo_root, to)?;
    let range = format!("{from}..{to}");
    let mut args = vec!["log".to_string(), range, "--pretty=format:%h %s".into(), "--reverse".into(), "--".into()];
    args.extend(paths.iter().map(|p| format!(":(literal){p}")));
    process::cmd("git", args).cwd(repo_root).read().map_err(Into::into)
}
