            detect_provider("claude-sonnet-4-5-20250929"),
            Provider::Anthropic
        );
    }

    #[test]
    fn test_detect_provider_non_claude() {
        assert_eq!(detect_provider("gpt-4"), Provider::OpenAI);
        assert_eq!(detect_provider("llama-3"), Provider::OpenAI);
    }
